∀ (a a_1 a_2 : ℕ) (a_3 : 0 < a) (a_4 : 0 < a_1) (a_5 : a + a_1 = a_2) (a_6 : a.Coprime a_1),
  { a := a, b := a_1, c := a_2, a_pos := a_3, b_pos := a_4, sum_eq := a_5, coprime_ab := a_6 } =
    { a := a, b := a_1, c := a_2, a_pos := a_3, b_pos := a_4, sum_eq := a_5, coprime_ab := a_6 }

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {N : GRWTSK.LinearAlgebra.OrientedRealLine.Line} (f : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M)
  (g : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv M N), (f.trans g).scale = g.scale * f.scale

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (self : GRWTSK.LinearAlgebra.OrientedRealLine.ComparisonCocycle object) (i : ι),
  (self.arrow i i).linearEquiv = LinearEquiv.refl ℝ (object i).Carrier

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (C : GRWTSK.LinearAlgebra.OrientedRealLine.ComparisonCocycle object) (i j k : ι),
  (C.arrow k i).scale * ((C.arrow j k).scale * (C.arrow i j).scale) = 1

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (self : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M) (x : L.Carrier),
  M.coordinate (self.linearEquiv x) = self.scale * L.coordinate x

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {common : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {comparison : (i : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) common}
  {common_1 : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {comparison_1 : (i : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) common_1},
  { common := common, comparison := comparison } = { common := common_1, comparison := comparison_1 } →
    common = common_1 ∧ comparison ≍ comparison_1

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {N : GRWTSK.LinearAlgebra.OrientedRealLine.Line} (f : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M)
  (g : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv M N), 0 < g.scale * f.scale

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (linearEquiv linearEquiv_1 : L.Carrier ≃ₗ[ℝ] M.Carrier) (e_linearEquiv : linearEquiv = linearEquiv_1)
  (scale scale_1 : ℝ) (e_scale : scale = scale_1) (scale_pos : 0 < scale)
  (realizes_scale : ∀ (x : L.Carrier), M.coordinate (linearEquiv x) = scale * L.coordinate x),
  { linearEquiv := linearEquiv, scale := scale, scale_pos := scale_pos, realizes_scale := realizes_scale } =
    { linearEquiv := linearEquiv_1, scale := scale_1, scale_pos := ⋯, realizes_scale := ⋯ }

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {linearEquiv : L.Carrier ≃ₗ[ℝ] M.Carrier} {scale : ℝ} {scale_pos : 0 < scale}
  {realizes_scale : ∀ (x : L.Carrier), M.coordinate (linearEquiv x) = scale * L.coordinate x}
  {linearEquiv_1 : L.Carrier ≃ₗ[ℝ] M.Carrier} {scale_1 : ℝ} {scale_pos_1 : 0 < scale_1}
  {realizes_scale_1 : ∀ (x : L.Carrier), M.coordinate (linearEquiv_1 x) = scale_1 * L.coordinate x},
  { linearEquiv := linearEquiv, scale := scale, scale_pos := scale_pos, realizes_scale := realizes_scale } =
      { linearEquiv := linearEquiv_1, scale := scale_1, scale_pos := scale_pos_1, realizes_scale := realizes_scale_1 } →
    linearEquiv = linearEquiv_1 ∧ scale = scale_1

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (D : GRWTSK.LinearAlgebra.OrientedRealLine.CommonComparison object),
  D.toCocycle = { arrow := fun i j => (D.comparison i).trans (D.comparison j).symm, identity := ⋯, cocycle := ⋯ }

∀ {Carrier : Type u} {addCommGroup : AddCommGroup Carrier} {moduleReal : _root_.Module ℝ Carrier}
  {coordinate : Carrier ≃ₗ[ℝ] ℝ} {Carrier_1 : Type u} {addCommGroup_1 : AddCommGroup Carrier_1}
  {moduleReal_1 : _root_.Module ℝ Carrier_1} {coordinate_1 : Carrier_1 ≃ₗ[ℝ] ℝ},
  { Carrier := Carrier, addCommGroup := addCommGroup, moduleReal := moduleReal, coordinate := coordinate } =
      { Carrier := Carrier_1, addCommGroup := addCommGroup_1, moduleReal := moduleReal_1, coordinate := coordinate_1 } →
    Carrier = Carrier_1 ∧ addCommGroup ≍ addCommGroup_1 ∧ moduleReal ≍ moduleReal_1 ∧ coordinate ≍ coordinate_1

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (self : GRWTSK.LinearAlgebra.OrientedRealLine.ComparisonCocycle object) (i j k : ι),
  ((self.arrow i j).trans (self.arrow j k)).linearEquiv = (self.arrow i k).linearEquiv

∀ {ι : Type u_2} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (D : GRWTSK.LinearAlgebra.OrientedRealLine.CommonComparison object) (i : ι),
  (D.comparison i).linearEquiv ≪≫ₗ (D.comparison i).linearEquiv.symm = LinearEquiv.refl ℝ (object i).Carrier

∀ {object : ℕ → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {edge : (i : ℕ) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) (object (i + 1))}
  {object_1 : ℕ → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {edge_1 : (i : ℕ) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object_1 i) (object_1 (i + 1))},
  { object := object, edge := edge } = { object := object_1, edge := edge_1 } → object = object_1 ∧ edge ≍ edge_1

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (C : GRWTSK.LinearAlgebra.OrientedRealLine.ComparisonCocycle object) (i j k : ι),
  (C.arrow j k).scale * (C.arrow i j).scale = (C.arrow i k).scale

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (f : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M) (y : M.Carrier),
  L.coordinate (f.linearEquiv.symm y) = f.scale⁻¹ * M.coordinate y

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (D : GRWTSK.LinearAlgebra.OrientedRealLine.CommonComparison object) (i j : ι),
  (D.toCocycle.arrow i j).scale = (D.comparison i).scale / (D.comparison j).scale

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (arrow arrow_1 : (i j : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) (object j))
  (e_arrow : arrow = arrow_1) (identity : ∀ (i : ι), (arrow i i).linearEquiv = LinearEquiv.refl ℝ (object i).Carrier)
  (cocycle : ∀ (i j k : ι), ((arrow i j).trans (arrow j k)).linearEquiv = (arrow i k).linearEquiv),
  { arrow := arrow, identity := identity, cocycle := cocycle } = { arrow := arrow_1, identity := ⋯, cocycle := ⋯ }

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (f g : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M),
  f.linearEquiv = g.linearEquiv → f.scale = g.scale

∀ {ι : Type u_1} {object : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {arrow : (i j : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) (object j)}
  {identity : ∀ (i : ι), (arrow i i).linearEquiv = LinearEquiv.refl ℝ (object i).Carrier}
  {cocycle : ∀ (i j k : ι), ((arrow i j).trans (arrow j k)).linearEquiv = (arrow i k).linearEquiv}
  {arrow_1 : (i j : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (object i) (object j)}
  {identity_1 : ∀ (i : ι), (arrow_1 i i).linearEquiv = LinearEquiv.refl ℝ (object i).Carrier}
  {cocycle_1 : ∀ (i j k : ι), ((arrow_1 i j).trans (arrow_1 j k)).linearEquiv = (arrow_1 i k).linearEquiv},
  { arrow := arrow, identity := identity, cocycle := cocycle } =
      { arrow := arrow_1, identity := identity_1, cocycle := cocycle_1 } →
    arrow = arrow_1

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (left right : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M),
  GRWTSK.LinearAlgebra.OrientedRealLine.routeDefect left right = left.scale / right.scale

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {N : GRWTSK.LinearAlgebra.OrientedRealLine.Line} (f : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M)
  (g : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv M N),
  f.trans g =
    { linearEquiv := f.linearEquiv ≪≫ₗ g.linearEquiv, scale := g.scale * f.scale, scale_pos := ⋯, realizes_scale := ⋯ }

∀ (s : ℝ) (hs : 0 < s),
  GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv.dilation s hs =
    { linearEquiv := LinearEquiv.smulOfNeZero ℝ ℝ s ⋯, scale := s, scale_pos := hs, realizes_scale := ⋯ }

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (f g : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M),
  GRWTSK.LinearAlgebra.OrientedRealLine.meanScale f g = (f.scale + g.scale) / 2

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (left right : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M),
  left.linearEquiv = right.linearEquiv → GRWTSK.LinearAlgebra.OrientedRealLine.routeDefect left right = 1

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (left right : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M) (j : ℝ),
  left.scale = j ^ 2 * right.scale → GRWTSK.LinearAlgebra.OrientedRealLine.routeDefect left right = j ^ 2

∀ {L : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {M : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  (left right : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv L M) (j : ℕ),
  1 < j → left.scale = ↑j ^ 2 * right.scale → left.linearEquiv ≠ right.linearEquiv

∀ {ι : Type u_1} {comparison : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {thetaObject : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line} {qObject : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {theta : (i : ι) → (thetaObject i).Carrier} {q : qObject.Carrier}
  {thetaMap : (i : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (thetaObject i) comparison}
  {qMap : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv qObject comparison} {coefficient error : ι → ℝ}
  {pointwise :
    ∀ (i : ι),
      comparison.coordinate ((thetaMap i).linearEquiv (theta i)) ≤
        coefficient i * comparison.coordinate (qMap.linearEquiv q) + error i}
  {comparison_1 : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {thetaObject_1 : ι → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {qObject_1 : GRWTSK.LinearAlgebra.OrientedRealLine.Line} {theta_1 : (i : ι) → (thetaObject_1 i).Carrier}
  {q_1 : qObject_1.Carrier}
  {thetaMap_1 : (i : ι) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (thetaObject_1 i) comparison_1}
  {qMap_1 : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv qObject_1 comparison_1}
  {coefficient_1 error_1 : ι → ℝ}
  {pointwise_1 :
    ∀ (i : ι),
      comparison_1.coordinate ((thetaMap_1 i).linearEquiv (theta_1 i)) ≤
        coefficient_1 i * comparison_1.coordinate (qMap_1.linearEquiv q_1) + error_1 i},
  { comparison := comparison, thetaObject := thetaObject, qObject := qObject, theta := theta, q := q,
        thetaMap := thetaMap, qMap := qMap, coefficient := coefficient, error := error, pointwise := pointwise } =
      { comparison := comparison_1, thetaObject := thetaObject_1, qObject := qObject_1, theta := theta_1, q := q_1,
        thetaMap := thetaMap_1, qMap := qMap_1, coefficient := coefficient_1, error := error_1,
        pointwise := pointwise_1 } →
    comparison = comparison_1 ∧
      thetaObject = thetaObject_1 ∧
        qObject = qObject_1 ∧
          theta ≍ theta_1 ∧
            q ≍ q_1 ∧ thetaMap ≍ thetaMap_1 ∧ qMap ≍ qMap_1 ∧ coefficient = coefficient_1 ∧ error = error_1

∀ {α : Type u_1} {interprets : GRWTSK.NumberTheory.ArithmeticGeometry.LogThetaComparison.SourceLocator → α → Prop}
  {x : α} (self : GRWTSK.NumberTheory.ArithmeticGeometry.LogThetaComparison.LocatedInterpretation interprets x),
  interprets self.locator x

∀ {J : Type u_1} {abstractTheta abstractQ : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {concreteTheta : J → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {concreteQ thetaDegree qDegree : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {thetaRealization :
    (j : J) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractTheta (concreteTheta j)}
  {thetaDegreeMap : (j : J) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (concreteTheta j) thetaDegree}
  {abstractComparison : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractTheta abstractQ}
  {qRealization : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractQ concreteQ}
  {qDegreeMap : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv concreteQ qDegree}
  {degreeComparison : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv thetaDegree qDegree}
  {abstractTheta_1 abstractQ_1 : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {concreteTheta_1 : J → GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {concreteQ_1 thetaDegree_1 qDegree_1 : GRWTSK.LinearAlgebra.OrientedRealLine.Line}
  {thetaRealization_1 :
    (j : J) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractTheta_1 (concreteTheta_1 j)}
  {thetaDegreeMap_1 :
    (j : J) → GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv (concreteTheta_1 j) thetaDegree_1}
  {abstractComparison_1 : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractTheta_1 abstractQ_1}
  {qRealization_1 : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv abstractQ_1 concreteQ_1}
  {qDegreeMap_1 : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv concreteQ_1 qDegree_1}
  {degreeComparison_1 : GRWTSK.LinearAlgebra.OrientedRealLine.PositiveScaleEquiv thetaDegree_1 qDegree_1},
  { abstractTheta := abstractTheta, abstractQ := abstractQ, concreteTheta := concreteTheta, concreteQ := concreteQ,
        thetaDegree := thetaDegree, qDegree := qDegree, thetaRealization := thetaRealization,
        thetaDegreeMap := thetaDegreeMap, abstractComparison := abstractComparison, qRealization := qRealization,
        qDegreeMap := qDegreeMap, degreeComparison := degreeComparison } =
      { abstractTheta := abstractTheta_1, abstractQ := abstractQ_1, concreteTheta := concreteTheta_1,
        concreteQ := concreteQ_1, thetaDegree := thetaDegree_1, qDegree := qDegree_1,
        thetaRealization := thetaRealization_1, thetaDegreeMap := thetaDegreeMap_1,
        abstractComparison := abstractComparison_1, qRealization := qRealization_1, qDegreeMap := qDegreeMap_1,
        degreeComparison := degreeComparison_1 } →
