      abstractQ = abstractQ_1 ∧
        concreteTheta = concreteTheta_1 ∧
          concreteQ = concreteQ_1 ∧
            thetaDegree = thetaDegree_1 ∧
              qDegree = qDegree_1 ∧
                thetaRealization ≍ thetaRealization_1 ∧
                  thetaDegreeMap ≍ thetaDegreeMap_1 ∧
                    abstractComparison ≍ abstractComparison_1 ∧
                      qRealization ≍ qRealization_1 ∧ qDegreeMap ≍ qDegreeMap_1 ∧ degreeComparison ≍ degreeComparison_1

